shell_commands:
cat << 'EOF' > fix_links.mjs
import fs from 'fs';
import path from 'path';

const specPath = 'specs/hal-engine-websocket-protocol/spec.md';
const testPath = 'src/transport/ws/messageHandler.test.ts';
const accTestPath = 'src/transport/conversationList.acceptance.test.ts';

let specContent = fs.readFileSync(specPath, 'utf8');
const testContent = fs.readFileSync(testPath, 'utf8').split('\n');
const accTestContent = fs.readFileSync(accTestPath, 'utf8').split('\n');

const linkRegex = /\[validated by: ([^\]]+)\]\(([^)]+)\)/g;

specContent = specContent.replace(linkRegex, (match, title, link) => {
  const [fileLink, hash] = link.split('#');
  if (!hash || !hash.startsWith('L')) return match;

  const targetFile = fileLink.endsWith('messageHandler.test.ts') ? testContent : 
                     fileLink.endsWith('conversationList.acceptance.test.ts') ? accTestContent : null;

  if (!targetFile) return match;

  const lineIndex = targetFile.findIndex(line => line.includes(title) && (line.includes('it(') || line.includes('describe(')));
  if (lineIndex !== -1) {
    const newLineNum = lineIndex + 1;
    return `[validated by: ${title}](${fileLink}#L${newLineNum})`;
  }
  return match;
});

fs.writeFileSync(specPath, specContent);
EOF
node fix_links.mjs
rm fix_links.mjs
